  values: Object.fromEntries(['speed','columns','rows','layers','brickMass'].map(id => [id, document.getElementById(id)?.value])),
  total: document.getElementById('brickTotal')?.textContent,
  status: document.getElementById('statusText')?.textContent,
  canvas: { width: document.getElementById('world')?.width, height: document.getElementById('world')?.height }
}));
const screenshot = await saveScreenshot(await page.screenshot(), 'crash-ready.png');
console.log(JSON.stringify({ data, errors, screenshot }, null, 2));
EOF

